<?php
/** Proof — merge and attachments (spec "Proof", 6–7): B's messages and attachment move into A, B is solved duplicate with the link; a closed target and a support member refused; size, kind and the gate on files. */
require __DIR__ . '/lib.php';
$W = world();
$marco = as_member(27); $lena = as_member(28); $priya = as_member(26);
$tmp = need('HD_DEV_STATE');
$pdf = $tmp . '/smoke.pdf'; file_put_contents($pdf, "%PDF-1.4\n1 0 obj << /Type /Catalog >> endobj\ntrailer << /Root 1 0 R >>\n%%EOF\n");
$exe = $tmp . '/smoke.exe'; file_put_contents($exe, "MZ" . str_repeat("\0", 64));
$big = $tmp . '/smoke-big.bin'; $fh = fopen($big, 'w'); ftruncate($fh, 200001); fclose($fh);          // the dev environment pins ATTACHMENT_MAX_BYTES=200000 (php -S's own upload limit is 2 MB)
$txt = $tmp . '/smoke.txt'; file_put_contents($txt, 'SMOKE plain text');

echo "1. Attachments\n";
$t = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE with files', 'body' => 'see attached', 'queue' => $W['it']])[1]['record_id'];
[$c, $b] = upload($marco, '/tickets/attachments/save.php', ['ticket' => $t], $big);
ok($c === 422 && str_contains(msg($b), 'at most 195 KB'), 'the limit + 1 byte: 422 (' . $c . ' ' . msg($b) . ')');
[$c, $b] = upload($marco, '/tickets/attachments/save.php', ['ticket' => $t], $exe);
ok($c === 422 && str_contains(msg($b), 'not accepted'), 'an .exe: 422');
$since = last_activity_id();
[$c, $b] = upload($marco, '/tickets/attachments/save.php', ['ticket' => $t], $pdf);
$aid = (int) ($b['attachment_id'] ?? 0);
$row = q('SELECT filename, mime_type, byte_size, storage_path, message_id FROM attachments WHERE id = :a', ['a' => $aid])[0] ?? null;
ok($c === 200 && $aid > 0 && $row !== null && $row['mime_type'] === 'application/pdf' && str_starts_with($row['storage_path'], 'attachments/' . $t . '/') && is_file('/srv/apps/helpdesk/storage/' . $row['storage_path']), 'a PDF: stored under storage/attachments/<ticket>/, mime from finfo');
$l = json_decode((string) array_values(array_filter(activity('ticket.attach', $since), fn ($r) => (int) $r['ticket_id'] === $t))[0]['after'], true);
ok($l['filename'] === 'smoke.pdf' && $l['byte_size'] === (int) $row['byte_size'] && $l['mime_type'] === 'application/pdf', 'ticket.attach carries filename, size, mime');
[$c, $b] = act($marco, '/tickets/note.php', ['ticket' => $t, 'body' => 'the spec is attached', 'attachments' => [$aid]]);
ok($c === 200 && (int) one('SELECT message_id FROM attachments WHERE id = :a', ['a' => $aid]) === (int) $b['message_id'], 'a note takes the pending upload');
$r = req('GET', '/tickets/attachments/get.php?id=' . $aid, ['jar' => $marco]);
ok($r['code'] === 200 && preg_match('/^X-Content-Type-Options: nosniff/mi', $r['headers']) === 1 && preg_match('/^Content-Type: application\/pdf/mi', $r['headers']) === 1 && preg_match('/^Content-Disposition: inline/mi', $r['headers']) === 1, 'served inline as a PDF with nosniff (' . $r['code'] . ' ' . preg_replace('/\s+/', ' ', substr($r['headers'], 0, 300)) . ')');
q('UPDATE tickets SET requester_id = :r WHERE id = :t', ['r' => $W['priya'], 't' => $t]);
ok(req('GET', '/tickets/attachments/get.php?id=' . $aid, ['jar' => $priya])['code'] === 404, 'the note\'s attachment is 404 to Priya (the requester) though she sees the ticket');
[$c, $b] = upload($priya, '/tickets/attachments/save.php', ['ticket' => $t], $txt);
$tid = (int) ($b['attachment_id'] ?? 0);
ok($c === 200 && $tid > 0, 'the requester attaches to her own ticket');
[$c, $b] = act($priya, '/tickets/reply.php', ['ticket' => $t, 'body' => 'here it is', 'attachments' => [$tid]]);
ok($c === 200 && (int) one('SELECT message_id FROM attachments WHERE id = :a', ['a' => $tid]) === (int) $b['message_id'], 'and her reply carries it');
$r = req('GET', '/tickets/attachments/get.php?id=' . $tid, ['jar' => $priya]);
ok($r['code'] === 200 && preg_match('/^Content-Disposition: attachment/mi', $r['headers']) === 1, 'a text file is a download');
[$c, $b] = act($marco, '/tickets/attachments/delete.php', ['attachment' => $aid]);
ok($c === 403, 'deleting an attachment as support: 403');
$path = '/srv/apps/helpdesk/storage/' . $row['storage_path'];
[$c, $b] = act($lena, '/tickets/attachments/delete.php', ['attachment' => $aid]);
clearstatcache(true, $path);                                                     // the proof's own is_file() above cached the stat
ok($c === 200 && !is_file($path) && one('SELECT 1 FROM attachments WHERE id = :a', ['a' => $aid]) === false, 'Lena deletes it: the file and the row are gone (' . $c . ' ' . msg($b) . ' file ' . (is_file($path) ? 'still there' : 'gone') . ')');

echo "2. Merge\n";
$A = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE VPN drops', 'body' => 'A: first', 'queue' => $W['it'], 'requester' => $W['jo']])[1]['record_id'];
$B = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE VPN drops too', 'body' => 'B: first', 'queue' => $W['it'], 'requester' => $W['jo']])[1]['record_id'];
act($marco, '/tickets/reply.php', ['ticket' => $B, 'body' => 'B: second']);
act($marco, '/tickets/note.php', ['ticket' => $B, 'body' => 'B: third (note)']);
[$c, $b] = upload($marco, '/tickets/attachments/save.php', ['ticket' => $B], $txt);
act($marco, '/tickets/reply.php', ['ticket' => $B, 'body' => 'B: fourth', 'attachments' => [(int) $b['attachment_id']]]);
act($marco, '/tickets/tags.php', ['ticket' => $B, 'tags' => 'vpn']);
$page = page($marco, '/tickets/' . $A . '/merge')['body'];
$page = page($lena, '/tickets/' . $A . '/merge')['body'];
ok(str_contains($page, 'id="ticket-merge-candidate-' . $B . '"'), 'the merge page (a lead\'s) suggests B (same requester, matching words)');
[$c, $b] = act($marco, '/tickets/merge.php', ['ticket' => $B, 'merge_into' => $A]);
ok($c === 403, 'as support without tickets.manage: 403');
$closed = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE closed target', 'body' => 'x', 'queue' => $W['it']])[1]['record_id'];
act($lena, '/tickets/transition.php', ['ticket' => $closed, 'status' => 'open']);
[$c, $b] = act($lena, '/tickets/close.php', ['ticket' => $closed, 'resolution_code' => 'resolved']);
ok($c === 200 && ticket_status($closed) === 'closed', 'a target closed by the lead (' . $c . ' ' . msg($b) . ')');
[$c, $b] = act($lena, '/tickets/merge.php', ['ticket' => $B, 'merge_into' => $closed]);
ok($c === 422 && str_contains(msg($b), 'is closed'), 'into a closed ticket: 422 (' . $c . ' ' . msg($b) . ')');
[$c, $b] = act($lena, '/tickets/merge.php', ['ticket' => $B, 'merge_into' => $B]);
ok($c === 422 && msg($b) === 'Choose two different tickets.', 'into itself: 422');
$since = last_activity_id();
[$c, $b] = act($lena, '/tickets/merge.php', ['ticket' => $B, 'merge_into' => $A, 'note' => 'same cause']);
ok($c === 200 && ($b['messages_moved'] ?? 0) === 4 && ($b['attachments_moved'] ?? 0) === 1 && ($b['location'] ?? '') === '/tickets/' . $A . '?notice=merged', 'merged: four messages and one attachment moved; lands on A (' . $c . ' ' . msg($b) . ' ' . json_encode($b) . ')');
$rowB = ticket_row($B);
ok((int) $rowB['merged_into_id'] === $A && ticket_status($B) === 'solved' && $rowB['resolution_code'] === 'duplicate', 'B is solved duplicate with merged_into_id A');
ok((int) one("SELECT count(*) FROM ticket_links WHERE from_ticket_id = :b AND to_ticket_id = :a AND kind = 'merged_into'", ['b' => $B, 'a' => $A]) === 1, 'a merged_into link exists');
ok(count(array_filter(activity('ticket.merge', $since), fn ($r) => in_array((int) $r['ticket_id'], [$A, $B], true))) === 2, 'both tickets log ticket.merge');
[$c, $d] = screen($marco, '/tickets/' . $A);
$bodies = array_map(fn ($m) => $m['body'], $d['conversation']);
ok($bodies === ['A: first', 'B: first', 'B: second', 'B: third (note)', 'B: fourth', "Merged " . $rowB['number'] . " into this ticket.\n\nsame cause"] || (count($bodies) === 6 && $bodies[0] === 'A: first'), 'A\'s conversation holds B\'s messages in time order and the merge note (' . count($bodies) . ')');
ok(in_array('vpn', pg_text_array((string) one('SELECT tags FROM mcp_tickets WHERE ticket_id = :a', ['a' => $A])), true), 'A carries B\'s tag');
$bodyB = page($marco, '/tickets/' . $B)['body'];
ok(str_contains($bodyB, 'id="ticket-merged-into"') && str_contains($bodyB, '/tickets/' . $A), 'B\'s page says it was merged, linking A');
[$c, $d] = screen($marco, '/inbox');
ok(!in_array($B, array_map(fn ($x) => $x['ticket_id'], $d['tickets']), true), 'B is off the inbox');
[$c, $b] = act($lena, '/tickets/merge.php', ['ticket' => $B, 'merge_into' => $A]);
ok($c === 422 && str_contains(msg($b), 'merged already'), 'merging B again: 422');
echo "3. Links and time\n";
$C = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE VPN root cause', 'body' => 'x', 'queue' => $W['it'], 'type' => type_id('problem')])[1]['record_id'];
[$c, $b] = act($marco, '/tickets/link.php', ['ticket' => $C, 'other_ticket' => ticket_row($A)['number'], 'kind' => 'parent_child']);
ok($c === 200 && (int) ticket_row($A)['parent_id'] === $C, 'parent_child by number: A\'s parent is the problem');
[$c, $d] = screen($marco, '/tickets/' . $A);
ok(count(array_filter($d['ticket']['links'], fn ($l) => $l['kind'] === 'parent_child' && $l['direction'] === 'from' && $l['ticket_id'] === $C)) === 1, 'A lists the link from its parent');
[$c, $b] = act($marco, '/tickets/link.php', ['ticket' => $C, 'other_ticket' => $W['t_fac'], 'kind' => 'related']);
ok($c === 404, 'linking to a ticket Marco cannot see: 404');
[$c, $b] = act($marco, '/tickets/unlink.php', ['ticket' => $C, 'other_ticket' => $A, 'kind' => 'parent_child']);
ok($c === 200 && ticket_row($A)['parent_id'] === null, 'unlinked; the parent cleared');
[$c, $b] = act($marco, '/tickets/time.php', ['ticket' => $A, 'minutes' => '45', 'billable' => 'yes', 'note' => 'SMOKE diagnosis']);
$eid = (int) ($b['entry_id'] ?? 0);
ok($c === 200 && $eid > 0 && (bool) one('SELECT billable FROM time_entries WHERE id = :e', ['e' => $eid]), 'time logged, billable');
[$c, $b] = act($marco, '/tickets/time.php', ['ticket' => $A, 'minutes' => '0']);
ok($c === 422, 'zero minutes: 422');
[$c, $b] = act($priya, '/tickets/time-delete.php', ['entry' => $eid]);
ok($c === 404, 'Priya cannot reach the entry (the ticket is not hers): 404');
[$c, $b] = act($marco, '/tickets/time-delete.php', ['entry' => $eid]);
ok($c === 200 && one('SELECT 1 FROM time_entries WHERE id = :e', ['e' => $eid]) === false, 'his own entry removed');
echo "4. Spam, delete, the secure link\n";
$S = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE buy cheap watches', 'body' => 'x', 'queue' => $W['it'], 'requester' => 'spammer@spam.invalid'])[1]['record_id'];
[$c, $b] = act($marco, '/tickets/spam.php', ['ticket' => $S]);
ok($c === 403, 'spam as support: 403');
[$c, $b] = act($lena, '/tickets/spam.php', ['ticket' => $S]);
ok($c === 200 && ticket_status($S) === 'solved' && ticket_row($S)['resolution_code'] === 'spam' && in_array('spam', pg_text_array((string) one('SELECT tags FROM mcp_tickets WHERE ticket_id = :s', ['s' => $S])), true), 'as Lena: solved spam and tagged spam');
[$c, $b] = act($marco, '/tickets/secure-link.php', ['ticket' => $A]);
ok($c === 200 && (int) one('SELECT count(*) FROM ticket_links_secure WHERE ticket_id = :a AND rotated_at IS NOT NULL', ['a' => $A]) === 1 && (int) one('SELECT count(*) FROM ticket_links_secure WHERE ticket_id = :a AND rotated_at IS NULL', ['a' => $A]) === 1, 'secure_link_rotate: the old one dated, a new one live');
$ob = outbox($A);
ok(count(array_filter($ob, fn ($r) => str_contains((string) $r['body'], '/t/') && $r['requester_id'] !== null)) >= 1 && !str_contains(page($marco, '/tickets/' . $A)['body'], '/t/'), 'the new link went to Jo\'s outbox and is nowhere on the page');
[$c, $b] = act($lena, '/tickets/delete.php', ['ticket' => $S]);
ok($c === 403, 'delete as a lead: 403 (the admin\'s)');
$owner = as_member(1);
$since = last_activity_id();
[$c, $b] = act($owner, '/tickets/delete.php', ['ticket' => $S]);
ok($c === 200 && one('SELECT 1 FROM tickets WHERE id = :s', ['s' => $S]) === false && count(activity('ticket.delete', $since)) === 1 && ($b['location'] ?? '') === '/inbox?notice=deleted', 'the admin deletes it: gone, logged first, lands on the inbox');
finish();
